# For each exit=0 record, missing == total required? (i.e., parser saw nothing)
man = {r['instance_id']: r for r in (json.loads(l) for l in open('corpus/manifest.jsonl'))}
ok=0; mismatch=[]
for r in recs:
    ex = [n for n in r['notes'] if n.startswith('exit=')][0]
    total = len(man[r['instance_id']]['fail_to_pass']) + len(man[r['instance_id']]['pass_to_pass'])
    if ex == 'exit=0':
        if len(r['missing']) == total and not r['failed']:
            ok += 1
        else:
            mismatch.append((r['record_id'], total, len(r['missing']), len(r['failed'])))
print("exit=0 records where parser saw NOTHING (missing==all required, failed==0):", ok, "of", sum(1 for r in recs if any(n=='exit=0' for n in r['notes'])))
