# exit=1 records: does failed + missing == total?
bad=[]
for r in recs:
    ex = [n for n in r['notes'] if n.startswith('exit=')][0]
    total = len(man[r['instance_id']]['fail_to_pass']) + len(man[r['instance_id']]['pass_to_pass'])
    if ex == 'exit=1':
        if len(r['failed']) + len(r['missing']) != total:
            bad.append((r['record_id'], total, len(r['failed']), len(r['missing'])))
print("exit=1 records where failed+missing != required:", len(bad), bad[:5])
EOF

