cd /workspace && python3 - <<'EOF'
import json, os

bugs = {}
for fn in os.listdir('corpus/patches'):
    if fn.endswith('.bug.patch'):
        instance = fn[:-len('.bug.patch')]
        bugs[instance] = open('corpus/patches/'+fn).read()

def reverse(patch):
    lines = []
    for l in patch.splitlines():
        if l.startswith('+++ ') or l.startswith('--- '):
            l = l.replace('/a/', '/b/') if ('/a/') in l else l.replace('/b/', '/a/')
        if l.startswith('+') and not l.startswith('+++'):
            lines.append('-' + l[1:])
        elif l.startswith('-') and not l.startswith('---'):
            lines.append('+' + l[1:])
        else:
            lines.append(l)
    return '\n'.join(lines) + '\n'

crecs = [json.loads(l) for l in open('corpus/records.jsonl')]
man = {r['instance_id']: r for r in (json.loads(l) for l in open('corpus/manifest.jsonl'))}
arch = {r['record_id']: r for r in (json.loads(l) for l in open('logs/historical/pass_a/regrade.jsonl'))}

rev_records = []
for c in crecs:
    if not c.get('patch'):
        continue
    sub = open('corpus/'+c['patch']).read()
    bug = bugs.get(c['instance_id'], '')
    norm = lambda s: s.replace('\r\n','\n').strip()
    if norm(reverse(sub)) == norm(bug):
        a = arch[c['record_id']]
        rev_records.append((c['record_id'], a['label'], a['reward']))
print("submissions that are EXACT reversals of their injected bug:", len(rev_records))
for r in rev_records:
    print('  ', r)
EOF

